script:
frappe.ui.form.on("Payment Request", {
	refresh(frm) {
		if (frm.is_new() || frm.doc.docstatus !== 0) {
			return;
		}

		frm.add_custom_button(
			__("Copy approval link"),
			() => {
				const path = `/app/payment-request/${encodeURIComponent(frm.doc.name)}`;
				const url = `${window.location.origin}${path}`;
				frappe.utils.copy_to_clipboard(url);
				frappe.show_alert({
					message: __(
						"Link copied. Send to the next approver via IM (login and approver role required)."
					),
					indicator: "green",
				});
			},
			__("Share")
		);

		// 工作流终态无 transition 时，Frappe form/workflow.js 的 setup_btn 不会去掉曾加在主/次按钮上的 hide，导致「提交」不显示（服务端权限正常）。
		if (!frappe.workflow.get_state_fieldname(frm.doctype)) {
			return;
		}
		setTimeout(() => {
			frappe.workflow.get_transitions(frm.doc).then((rows) => {
				if (rows && rows.length) {
					return;
				}
				frm.page.btn_primary.removeClass("hide");
				frm.page.btn_secondary.removeClass("hide");
			});
		}, 150);
	},
});
